from collect import append_tag

def test_no_leak_between_calls():
    first = append_tag("a")
    second = append_tag("b")
    assert first == ["a"]
    assert second == ["b"]

def test_explicit_list_reused():
    box = ["x"]
    assert append_tag("y", box) == ["x", "y"]


from recursion import flatten

def test_flatten_empty_nested():
    assert flatten([1, [], [2, [3]]]) == [1, 2, 3]

def test_flatten_all_empty():
    assert flatten([[], [], []]) == []

def test_flatten_deep():
    assert flatten([1, [2, [3, [4]]]]) == [1, 2, 3, 4]
